def _state_anchor_path(path: str) -> str:
    """The sidecar path mirroring one v3 header checkpoint path."""
    return path + ".state"


def _state_anchor_hash(
    generation: int,
    account: str,
    anchor: dict,
    document: object,
    trust: object,
) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    body = {
        "v": STATE_ANCHOR_VERSION,
        "generation": generation,
        "account": account,
        "anchor": anchor,
        "document": document,
        "trust": trust,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _validate_state_anchor_shape(data: object) -> dict:
    """Strictly validate one version-1 state-anchor sidecar document.

    Exact top-level key order ``v, generation, account, anchor, document,
    trust, hash``; ``v`` must be 1 and ``generation`` a positive plain
    integer; ``account`` is a 64-lowercase-hex account; ``anchor`` carries
    the closed ``height, block_hash, state_root`` shape (non-negative
    non-boolean height, two 64-lowercase-hex hashes). ``document`` and
    ``trust`` are preserved verbatim (their own contract is re-verified on
    load by :func:`verify_state_proof`). The recorded ``hash`` is
    recomputed over the other fields last, so a re-sealed tampered file is
    still corruption. Any defect is existing-state corruption.
    """
    if not isinstance(data, dict) or tuple(data.keys()) != STATE_ANCHOR_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != STATE_ANCHOR_VERSION:
        raise _CheckpointError(ERR_STATE)
    generation = data["generation"]
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    account = data["account"]
    if not crypto.is_hex64(account):
        raise _CheckpointError(ERR_STATE)
    raw_anchor = data["anchor"]
    if (
        not isinstance(raw_anchor, dict)
        or tuple(raw_anchor.keys()) != STATE_ANCHOR_ANCHOR_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(raw_anchor["height"]) or raw_anchor["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw_anchor["block_hash"]):
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw_anchor["state_root"]):
        raise _CheckpointError(ERR_STATE)
    anchor = {key: raw_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS}
    document = data["document"]
    trust = data["trust"]
    digest = data["hash"]
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)
    if _state_anchor_hash(generation, account, anchor, document, trust) != digest:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": STATE_ANCHOR_VERSION,
        "generation": generation,
        "account": account,
        "anchor": anchor,
        "document": document,
        "trust": trust,
        "hash": digest,
    }


def _load_state_anchor(path: str) -> dict | None:
    """Strictly load the state-anchor sidecar at ``path + ".state"``.

    Returns None when the sidecar is absent. An unreadable file is ``io``;
    bad UTF-8, malformed JSON and every shape/key-order/type/digest defect
    is ``state``. The sidecar is never truncated or rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_state_anchor_shape(data)


def _parse_state_anchor_arguments(
    document: object, account: object, trust: object
) -> tuple[dict, dict, int, str, dict]:
    """Stage-1 (input) structural check shared with :func:`verify_state_proof`.

    Validates the pinned account, the exact ``state, proof, auth`` document
    shape (key order and raw types, hex encodings) and
    ``trust.audit_signers``, but performs no signer lookup, signature or
    Merkle work — so argument/structure/encoding defects surface as
    ``input`` before any persisted state is loaded.
    """
    if not crypto.is_hex64(account):
        raise _Failure(ERR_INPUT)
    if not isinstance(document, dict) or tuple(document.keys()) != (
        ATTESTED_STATE_PROOF_KEYS
    ):
        raise _Failure(ERR_INPUT)
    state = _parse_state_root_document(document["state"])
    _proof = _parse_state_proof_document(document["proof"])
    raw_auth = document["auth"]
    if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != (
        STATE_PROOF_AUTH_KEYS
    ):
        raise _Failure(ERR_INPUT)
    key_version = raw_auth["key_version"]
    signature = raw_auth["signature"]
    if not _is_int(key_version) or key_version < 1:
        raise _Failure(ERR_INPUT)
    if not isinstance(signature, str) or not crypto.is_hex128(signature):
        raise _Failure(ERR_INPUT)
    signers = _validate_header_trust(trust)
    return state, _proof, key_version, signature, signers


def _reverify_stored_state_anchor(stored: dict, branch: dict) -> None:
    """Re-verify a loaded sidecar against its own trust and the branch.

    The stored document is re-verified exactly as a fresh state proof (it
    was valid when written, so any failure means the stored bytes are
    defective) and the recorded anchor must name a header on the replayed
    current branch (a fork pruned by a reorg can no longer anchor state).
    Every defect is ``state``; the sidecar is left untouched.
    """
    result = verify_state_proof(
        stored["document"], stored["account"], stored["trust"]
    )
    if not result.get("ok"):
        raise _CheckpointError(ERR_STATE)
    anchor = stored["anchor"]
    # The stored anchor is a deterministic projection of the saved proof; a
    # re-sealed file that moved the anchor off the proof is corruption.
    if anchor != {
        "height": result["height"],
        "block_hash": result["block_hash"],
        "state_root": result["state_root"],
    }:
        raise _CheckpointError(ERR_STATE)
    # The old anchor must still name a header on the replayed current branch
    # (a reorg can never prune at or below finalized, so a miss here means a
    # hand-crafted/diverged sidecar).
    entry = branch.get(anchor["height"])
    if entry is None or entry[0] != anchor["block_hash"]:
        raise _CheckpointError(ERR_STATE)


def advance_state_anchor(
    path: object,
    document: object,
    account: object,
    trust: object,
) -> dict:
    """Verify a signed account-state proof and pin it as a state anchor.

    The state anchor is stored in the sidecar at ``path + ".state"`` next
    to a version-3 header checkpoint at ``path`` (pure library API; the
    HTTP/CLI surface is unchanged). ``document``/``account``/``trust`` are
    exactly the :func:`verify_state_proof` arguments: the decoded
    ``GET /v1/accounts/{account}/attested-proof`` document (key order
    ``state, proof, auth``), the caller-pinned 64-lowercase-hex account and
    the trust document carrying ``audit_signers``.

    The proof is fully verified first. Its ``state.height`` and
    ``state.block_hash`` must then equal the header checkpoint's
    irreversible ``finalized`` boundary; the new anchor is exactly
    ``{height, block_hash, state_root}``.

    The header file and the sidecar are loaded together under the per-path
    lock shared with every other same-path operation: the header
    checkpoint must exist (missing is ``io``) and is strictly replayed, an
    existing sidecar is strictly loaded and its stored proof re-verified,
    with its old anchor checked for current-branch ownership (any defect is
    ``state``). Generation starts at 1; re-submitting the same account with
    the same anchor is idempotent (no disk write, generation held); a
    higher finalized boundary increments the generation once. A different
    account, a lower height, or the same height with a different
    block hash/state root is ``integrity``.

    The sidecar is one compact UTF-8 JSON document (non-ASCII unescaped)
    with one trailing LF, top-level key order
    ``v, generation, account, anchor, document, trust, hash``: ``v`` is 1,
    ``generation`` a positive non-boolean integer, ``anchor`` has key order
    ``height, block_hash, state_root``, ``document``/``trust`` are stored
    verbatim and ``hash`` is the lowercase-hex SHA-256 of the self-excluding
    canonical JSON bytes. It is fsynced and ``os.replace``d atomically; a
    failed write restores the original bytes best-effort.

    Success returns ``{"ok": True, "generation", "anchor"}`` in that key
    order; failure returns only ``{"ok": False, "error": category}`` with
    category one of ``input`` (parameters, structure or encoding), ``auth``
    (unknown key version or a bad signature), ``integrity`` (finalized
    binding, account change, regression or a same-height value mismatch),
    ``state`` (a corrupt stored header checkpoint or sidecar) and ``io``
    (the header file is missing, or a read/write fails). Nothing is raised
    and a failure never changes a file.
    """
    # Argument/structure shape is checked before any file work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)
    try:
        _parse_state_anchor_arguments(document, account, trust)
    except _Failure as failure:
        return _failed_advance(failure.category)
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather
        # than crash the caller.
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        # Stage 2 (state/io): strictly load and replay the v3 header
        # checkpoint (it must exist — a state anchor can never outlive its
        # header file) together with any existing sidecar.
        try:
            loaded = _load_header_checkpoint_document(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            return _failed_advance(ERR_STATE)
        if loaded is None:
            return _failed_advance(ERR_IO)
        checkpoint, _step_tips, branch = loaded
        finalized = checkpoint["finalized"]

        state_path = _state_anchor_path(path)
        try:
            stored = _load_state_anchor(state_path)
            if stored is not None:
                _reverify_stored_state_anchor(stored, branch)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            return _failed_advance(ERR_STATE)

        # Stage 3 (auth) + the proof's own binding/Merkle checks
        # (integrity): re-run the full contract now that persisted state is
        # settled, mirroring apply_finality's load-before-authenticate.
        result = verify_state_proof(document, account, trust)
        if not result.get("ok"):
            return {"ok": False, "error": result["error"]}
        state = document["state"]
        new_anchor = {
            "height": state["height"],
            "block_hash": state["block_hash"],
            "state_root": state["state_root"],
        }

        # Stage 4 (integrity): the proof must pin exactly the checkpoint's
        # finalized boundary.
        if (
            new_anchor["height"] != finalized["height"]
            or new_anchor["block_hash"] != finalized["block_hash"]
        ):
            return _failed_advance(ERR_INTEGRITY)

        if stored is None:
            next_generation = 1
        else:
            # A state anchor is bound to one account; switching accounts on
            # the same sidecar is an integrity failure, not a replacement.
            if account != stored["account"]:
                return _failed_advance(ERR_INTEGRITY)
            old_anchor = stored["anchor"]
            if new_anchor == old_anchor:
                # Same account and same anchor: idempotent. The proof was
                # re-verified above, so the file bytes stay exactly as they
                # were and the generation holds even for an equivalent
                # freshly-signed document.
                return {
                    "ok": True,
                    "generation": stored["generation"],
                    "anchor": {
                        key: old_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS
                    },
                }
            # The boundary may only advance: a lower height regresses, and
            # the same height with a different block hash/state root is a
            # conflicting value. A higher finalized height advances.
            if new_anchor["height"] < old_anchor["height"]:
                return _failed_advance(ERR_INTEGRITY)
            if new_anchor["height"] == old_anchor["height"]:
                return _failed_advance(ERR_INTEGRITY)
            next_generation = stored["generation"] + 1

        ordered = {
            "v": STATE_ANCHOR_VERSION,
            "generation": next_generation,
            "account": account,
            "anchor": new_anchor,
            "document": document,
            "trust": trust,
        }
        ordered["hash"] = _state_anchor_hash(
            next_generation, account, new_anchor, document, trust
        )
        try:
            payload = _serialize_document(ordered)
        except (TypeError, ValueError):
            # A document/trust value JSON cannot re-serialize is a
            # caller-side defect, never a partial write (serialization
            # happens before the temp file is touched).
            return _failed_advance(ERR_INPUT)
        try:
            original = _read_bytes_or_none(state_path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_bytes(state_path, payload)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(state_path, original)
            return _failed_advance(ERR_IO)

        return {
            "ok": True,
            "generation": next_generation,
            "anchor": {key: new_anchor[key] for key in STATE_ANCHOR_ANCHOR_KEYS},
        }

def advance_finalized_headers(
    path: object,
    documents: object,
    finalities: object,
    anchor: object,
    tip_hash: object,
    trust: object,
) -> dict:
    """Advance a header checkpoint and its finality boundary atomically.

    ``documents``/``anchor``/``tip_hash``/``trust`` are exactly the
    :func:`advance_headers` arguments: ``documents`` is an ordered,
    non-empty batch of ``GET /v1/chain/headers`` pages verified with
    :func:`verify_header_pages`; the first use of ``path`` requires a
    legal ``anchor`` while a later call passes ``None`` or the stored
    tip's ``{height, block_hash}``. ``finalities`` is a non-empty,
    ordered array of signed ``GET /v1/chain/finality`` credentials kept
    under the exact :func:`apply_finalities` contract (key order
    ``finalized, tip, auth``, nested types, the ``ledger-finality-v1``
    Ed25519 envelope against ``trust.audit_signers``).

    Processing is staged and all-or-nothing:

    1. **input** — ``path``/``tip_hash``, the non-empty ``documents``
       and ``finalities`` arrays, every credential's exact key order and
       raw types and the trust signers are settled before any file or
       signature work.
    2. **state/io** — the checkpoint at ``path`` is strictly loaded and
       fully replayed under the shared per-path lock (a missing file
       opens a new checkpoint exactly as :func:`advance_headers` does; a
       parse, key-order, digest or replay defect is ``state``).
    3. **auth** — every credential envelope is verified in array order
       (an unknown key version or a failed signature is ``auth``).
    4. **integrity** — the header batch is verified and must legally
       advance the stored tip (the :func:`advance_headers` rules), then
       the credentials walk the freshly advanced branch in order: each
       item's ``tip`` must match the same-height header's hash and
       status, tip heights must not decrease, finalized heights must
       strictly increase, and each target must name the checkpoint
       anchor or a confirmed header no higher than its own tip. The
       batch as a whole may not end below or beside the stored boundary.

    Only a fully valid call appends exactly one ``linear`` step and
    writes the last credential's boundary: the generation is incremented
    exactly once and the file atomically replaced in the version-3
    format (same serialization and hash rules as
    :func:`advance_headers`). A call whose appended step equals the
    stored last step and whose final boundary equals the stored one is
    idempotent: the file bytes stay exactly as they were and the
    generation holds. Success returns ``{"ok": True, "generation",
    "tip", "finalized", "applied"}`` in that key order with ``tip`` the
    new chain descriptor, ``finalized`` the last credential's closed
    boundary (key order ``height, block_hash``) and ``applied`` the
    number of credentials. Failure returns only ``{"ok": False,
    "error": category}`` with category one of ``input`` (argument, array
    or document shape/types), ``auth`` (an unknown version or a failed
    signature), ``integrity`` (chain, tip, ordering, branch or boundary
    defects), ``state`` (an existing checkpoint fails its parse,
    key-order, digest or replay checks; it is never truncated or
    rebuilt) and ``io`` (a read/write failure; a failed write restores
    the original bytes best-effort). Nothing is raised and a failed call
    never changes the file bytes.
    """
    # Argument shape is validated before any file or verification work.
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)
    if not isinstance(tip_hash, str) or not crypto.is_hex64(tip_hash):
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        # Stage 1 (input): the batch shapes, every credential's exact key
        # order and raw types and the trust signers are settled before
        # any file or signature work — structure precedes state and
        # trust.
        if not isinstance(documents, list) or not documents:
            return _failed_advance(ERR_INPUT)
        if not isinstance(finalities, list) or not finalities:
            return _failed_advance(ERR_INPUT)
        try:
            parsed = [
                _parse_finality_document(document) for document in finalities
            ]
            signers = _validate_header_trust(trust)
        except _Failure as failure:
            return _failed_advance(failure.category)
        except Exception:
            # Defensive: structurally unforeseeable inputs must report
            # rather than crash the caller.
            return _failed_advance(ERR_INPUT)

        # Stage 2 (state/io): the persisted checkpoint is strictly loaded
        # and fully replayed under the shared per-path lock before
        # anything is judged; a first use opens the checkpoint exactly as
        # advance_headers does.
        try:
            loaded = _load_header_checkpoint_document(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            # Defensive: an unreadable-by-surprise checkpoint must report
            # rather than crash the caller.
            return _failed_advance(ERR_STATE)

        if loaded is None:
            # First use: the caller must pin a legal anchor. The anchor
            # is also the initial finalized boundary.
            expected_anchor = _validate_header_anchor_argument(anchor)
            if expected_anchor is None:
                return _failed_advance(ERR_INPUT)
            generation = 0
            file_anchor = expected_anchor
            finalized = {key: expected_anchor[key] for key in HEADER_ANCHOR_KEYS}
            steps: list[dict] = []
            stored_tip: dict | None = None
            branch: dict[int, tuple[str, str]] = {
                expected_anchor["height"]: (
                    expected_anchor["block_hash"],
                    STATUS_CONFIRMED,
                )
            }
        else:
            checkpoint, _step_tips, branch = loaded
            generation = checkpoint["generation"]
            file_anchor = checkpoint["anchor"]
            finalized = checkpoint["finalized"]
            steps = checkpoint["steps"]
            stored_tip = checkpoint["tip"]
            if anchor is None:
                # Continue the continuous chain from the stored closed tip.
                expected_anchor = {
                    "height": stored_tip["height"],
                    "block_hash": stored_tip["tip_hash"],
                }
            else:
                expected_anchor = _validate_header_anchor_argument(anchor)
                if (
                    expected_anchor is None
                    or expected_anchor
                    != {
                        "height": stored_tip["height"],
                        "block_hash": stored_tip["tip_hash"],
                    }
                ):
                    return _failed_advance(ERR_INPUT)

        step = {
            "kind": "linear",
            "tip_hash": tip_hash,
            "trust": trust,
            "documents": documents,
            "locators": None,
        }
        # An exact resubmission of the stored last step was verified when
        # it was stored and re-verified by the load replay above, so it
        # is neither re-verified nor appended again.
        same_step = bool(steps) and step == steps[-1]

        # Stage 3 (auth): every credential envelope is verified in array
        # order. A later credential is never trusted because an earlier
        # one was.
        try:
            for document, (_target, _tip, key_version, signature) in zip(
                finalities, parsed
            ):
                _authenticate_finality(
                    document, key_version, signature, signers
                )
        except _Failure as failure:
            return _failed_advance(failure.category)

        # The header batch is verified exactly as advance_headers
        # verifies it, and the new tip may never drop in height.
        if same_step:
            new_tip = stored_tip
        else:
            try:
                result = verify_header_pages(
                    documents, expected_anchor, tip_hash, trust
                )
            except Exception:
                # Defensive: the verifiers never raise, but an
                # unforeseeable input must report rather than crash.
                return _failed_advance(ERR_INPUT)
            if not result.get("ok"):
                return {"ok": False, "error": result["error"]}
            new_tip = result["tip"]
            if stored_tip is not None and not _header_tip_advances(
                stored_tip, new_tip
            ):
                return _failed_advance(ERR_INTEGRITY)
            # Extend the replayed branch with the batch's headers so the
            # credentials below are judged against the advanced chain.
            for document in documents:
                for header in document["headers"]:
                    branch[header["height"]] = (
                        header["block_hash"],
                        header["status"],
                    )
            # The closing tip is authoritative for its height (an empty
            # final page settles the tip's status without headers).
            branch[new_tip["height"]] = (new_tip["tip_hash"], new_tip["status"])

        # Stage 4 (integrity): walk the credential batch in order against
        # the freshly advanced branch, exactly as apply_finalities walks
        # the replayed one. Inside the batch finalized heights rise
        # strictly and tip heights never fall; each item's tip must name
        # the branch header at that height (same hash and status) and its
        # finalized target must be the checkpoint anchor or a confirmed
        # header no higher than that tip.
        previous_target_height: int | None = None
        previous_tip_height: int | None = None
        last_target: dict | None = None
        try:
            for target, cred_tip, _version, _signature in parsed:
                tip_entry = branch.get(cred_tip["height"])
                if tip_entry is None or tip_entry[0] != cred_tip["tip_hash"]:
                    raise _Failure(ERR_INTEGRITY)
                if tip_entry[1] != cred_tip["status"]:
                    raise _Failure(ERR_INTEGRITY)
                if (
                    previous_tip_height is not None
                    and cred_tip["height"] < previous_tip_height
                ):
                    raise _Failure(ERR_INTEGRITY)
                previous_tip_height = cred_tip["height"]
                if (
                    previous_target_height is not None
                    and target["height"] <= previous_target_height
                ):
                    raise _Failure(ERR_INTEGRITY)
                previous_target_height = target["height"]
                if target["height"] > cred_tip["height"]:
                    raise _Failure(ERR_INTEGRITY)
                entry = branch.get(target["height"])
                if entry is None or entry[0] != target["block_hash"]:
                    raise _Failure(ERR_INTEGRITY)
                if target != file_anchor and entry[1] != STATUS_CONFIRMED:
                    raise _Failure(ERR_INTEGRITY)
                last_target = target
        except _Failure as failure:
            return _failed_advance(failure.category)
        assert last_target is not None  # finalities is shape-guaranteed non-empty

        # The batch as a whole must not move the stored boundary
        # backwards or sideways.
        if last_target["height"] < finalized["height"] or (
            last_target["height"] == finalized["height"]
            and last_target["block_hash"] != finalized["block_hash"]
        ):
            return _failed_advance(ERR_INTEGRITY)

        if same_step and last_target == finalized:
            # Idempotent: the appended step and the final boundary both
            # equal the stored ones, so the file bytes stay exactly as
            # they were and the generation holds.
            return {
                "ok": True,
                "generation": generation,
                "tip": stored_tip,
                "finalized": {key: finalized[key] for key in HEADER_ANCHOR_KEYS},
                "applied": len(parsed),
            }

        next_generation = generation + 1
        new_steps = steps if same_step else steps + [step]
        checkpoint = {
            "v": HEADER_CHECKPOINT_VERSION,
            "generation": next_generation,
            "anchor": file_anchor,
            "tip": new_tip,
            "finalized": last_target,
            "steps": new_steps,
        }
        checkpoint["hash"] = _header_checkpoint_hash(
            HEADER_CHECKPOINT_VERSION,
            next_generation,
            file_anchor,
            new_tip,
            last_target,
            new_steps,
        )

        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_header_checkpoint(path, checkpoint)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(path, original)
            return _failed_advance(ERR_IO)
        except (TypeError, ValueError):
            # A trust/document value JSON cannot serialize (verification
            # only judges the fields it pins) is a caller-side defect.
            return _failed_advance(ERR_INPUT)

        return {
            "ok": True,
            "generation": next_generation,
            "tip": new_tip,
            "finalized": {key: last_target[key] for key in HEADER_ANCHOR_KEYS},
            "applied": len(parsed),
        }


# Fixed success key order returned by :func:`reorg_finalized_headers`.
REORG_FINALIZED_HEADERS_RESULT_KEYS = (
    "ok",
    "generation",
    "tip",
    "finalized",
    "replaced",
    "applied",
)


def reorg_finalized_headers(
    path: object,

def _state_proof_bytes(unsigned: dict) -> bytes:
    """The signed bytes of an attested state proof without its ``auth`` envelope:
    ``UTF8("ledger-state-proof-v1") || canonical_json({state, proof})``.
    """
    return STATE_PROOF_DOMAIN.encode("utf-8") + _canonical_json_bytes(unsigned)


def sign_state_proof(
    private_key_hex: str,
    key_version: int,
    state: dict,
    proof: dict,
) -> dict | None:
    """Build the ``{key_version, signature}`` envelope of an attested state proof.

    The signature is an Ed25519 signature over
    ``SHA256(UTF8("ledger-state-proof-v1") || canonical_json({state, proof}))``.
    Returns None when the private key is malformed.
    """
    unsigned = {"state": state, "proof": proof}
    digest = hashlib.sha256(_state_proof_bytes(unsigned)).digest()
    signature = crypto.sign_message(private_key_hex, digest)
    if signature is None:
        return None
    return {"key_version": key_version, "signature": signature}


def _parse_state_root_document(raw: object) -> dict:
    """Exact key order and raw types of the state-root sub-document."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != STATE_ROOT_DOC_KEYS:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["state_root"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["height"]) or raw["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["block_hash"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["account_count"]) or raw["account_count"] < 0:
        raise _Failure(ERR_INPUT)
    return {key: raw[key] for key in STATE_ROOT_DOC_KEYS}


def _parse_state_proof_document(raw: object) -> dict:
    """Exact key order and raw types of the account-state-proof sub-document."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != STATE_PROOF_DOC_KEYS:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["account"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["balance"]) or raw["balance"] < 0:
        raise _Failure(ERR_INPUT)
    transactions = raw["confirmed_transactions"]
    if not isinstance(transactions, list) or any(
        not crypto.is_hex64(tx_id) for tx_id in transactions
    ):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["index"]) or raw["index"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["state_root"]):
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["height"]) or raw["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["block_hash"]):
        raise _Failure(ERR_INPUT)
    siblings = raw["siblings"]
    if not isinstance(siblings, list) or len(siblings) > crypto.MAX_MERKLE_DEPTH:
        raise _Failure(ERR_INPUT)
    for item in siblings:
        if not isinstance(item, dict) or tuple(item.keys()) != STATE_PROOF_SIBLING_KEYS:
            raise _Failure(ERR_INPUT)
        direction = item["direction"]
        if not isinstance(direction, str) or direction not in ("left", "right"):
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(item["hash"]):
            raise _Failure(ERR_INPUT)
    return {key: raw[key] for key in STATE_PROOF_DOC_KEYS}


def verify_state_proof(document: object, account: object, trust: object) -> dict:
    """Offline-verify one ``GET /v1/accounts/{account}/attested-proof`` document.

    ``document`` is the decoded response with the exact top-level key order
    ``state, proof, auth``: ``state`` is the state-root document
    (``state_root, height, block_hash, account_count`` in that order),
    ``proof`` is the account-state inclusion proof
    (``account, balance, confirmed_transactions, index, state_root, height,
    block_hash, siblings`` in that order, each sibling ``direction, hash``)
    and ``auth`` is ``{key_version, signature}``. ``account`` is the
    caller-pinned 64-lowercase-hex account the proof must name; ``trust``
    must carry an ``audit_signers`` list exactly as for
    :func:`verify_header_page`.

    Verification, in order:

    1. **input** — exact key order and raw types of every (sub-)document,
       64/128-lowercase-hex encodings, the pinned ``account`` shape and the
       ``trust.audit_signers`` list;
    2. **auth** — the envelope's ``key_version`` must resolve in
       ``audit_signers`` and the Ed25519 signature must verify over
       ``SHA256(UTF8("ledger-state-proof-v1") || canonical_json({state,
       proof}))`` (an unknown version or a bad signature is ``auth``);
    3. **integrity** — the proof must name the pinned account, its
       ``state_root``/``height``/``block_hash`` must bind to the state
       document, ``index`` must lie within ``account_count`` and the
       leaf-to-root sibling path must recompute the leaf and the state
       root under the ledger pairing rules.

    Success returns ``{"ok": True, "account", "height", "block_hash",
    "state_root"}`` in that key order; failure returns only
    ``{"ok": False, "error": "input"|"auth"|"integrity"}``. Never raises
    for malformed input.
    """
    try:
        # Stage 1 (input): exact key order, types, hex encodings and trust.
        if not crypto.is_hex64(account):
            raise _Failure(ERR_INPUT)
        if not isinstance(document, dict) or tuple(document.keys()) != (
            ATTESTED_STATE_PROOF_KEYS
        ):
            raise _Failure(ERR_INPUT)
        state = _parse_state_root_document(document["state"])
        proof = _parse_state_proof_document(document["proof"])
        raw_auth = document["auth"]
        if not isinstance(raw_auth, dict) or tuple(raw_auth.keys()) != (
            STATE_PROOF_AUTH_KEYS
        ):
            raise _Failure(ERR_INPUT)
        key_version = raw_auth["key_version"]
        signature = raw_auth["signature"]
        if not _is_int(key_version) or key_version < 1:
            raise _Failure(ERR_INPUT)
        if not isinstance(signature, str) or not crypto.is_hex128(signature):
            raise _Failure(ERR_INPUT)
        signers = _validate_header_trust(trust)

        # Stage 2 (auth): signer lookup by key version and the Ed25519
        # signature over the domain-prefixed canonical bytes of {state, proof}.
        public_key = signers.get(key_version)
        if public_key is None:
            raise _Failure(ERR_AUTH)
        unsigned = {"state": state, "proof": proof}
        digest = hashlib.sha256(_state_proof_bytes(unsigned)).digest()
        if not crypto.verify_signature(public_key, digest, signature):
            raise _Failure(ERR_AUTH)

        # Stage 3 (integrity): account binding, state/proof anchor binding,
        # index range and the recomputed Merkle inclusion path.
        if proof["account"] != account:
            raise _Failure(ERR_INTEGRITY)
        if (
            proof["state_root"] != state["state_root"]
            or proof["height"] != state["height"]
            or proof["block_hash"] != state["block_hash"]
        ):
            raise _Failure(ERR_INTEGRITY)
        if not 0 <= proof["index"] < state["account_count"]:
            raise _Failure(ERR_INTEGRITY)
        if not crypto.verify_account_proof(
            proof,
            state["state_root"],
            state["height"],
            state["block_hash"],
        ):
            raise _Failure(ERR_INTEGRITY)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather than
        # crash the verifying process.
        return {"ok": False, "error": ERR_INPUT}
    return {
        "ok": True,
        "account": proof["account"],
        "height": state["height"],
        "block_hash": state["block_hash"],
        "state_root": state["state_root"],
    }


def verify_header_page(
    document: object,
    anchor: object,
    tip_hash: object,
    trust: object,
) -> dict:
    """Offline-verify one signed ``GET /v1/chain/headers`` page.

    ``document`` is the decoded response with the exact top-level key order
    ``anchor, headers, tip, auth``: ``anchor`` is ``{height, block_hash}``
    (key order ``height, block_hash``), ``headers`` is an ascending list of
    ``{height, prev_hash, merkle_root, block_hash, status}`` header items,
    ``tip`` is the chain descriptor S (``tip_hash, height, length, status``)
    and ``auth`` is ``{key_version, signature}``. ``anchor`` is the
    caller-pinned anchor the page's ``anchor`` must strictly equal;
    ``tip_hash`` is the caller-pinned chain tip the page's ``tip`` must
    name. ``trust`` must carry an ``audit_signers`` list; the envelope's
    ``key_version`` selects that version's public key.

    Verification, in order: strict key order and types (``input``), signer
    lookup by ``key_version`` and the Ed25519 signature over
    ``SHA256(UTF8("ledger-headers-v1") || canonical_json(document without
    auth))`` (unknown version/key or a signature that does not verify is
    ``auth``), the pinned anchor, the recomputed header hashes and prev_hash
    links (heights consecutive from the anchor, pending only at the page
    tail), and the tip descriptor (``integrity``). An empty page is valid
    only when its anchor is the pinned tip; a page ending before the tip is
    a valid non-final pagination page. Never raises for malformed input.

    Returns ``{"ok": True, "anchor", "tip", "verified_block_hashes"}`` on
    success (the hashes in ascending page order, empty for an anchor=tip
    page) or ``{"ok": False, "error": "input"|"auth"|"integrity"}``.

def _load_receipt_index(path: str) -> dict | None:
    """Strictly load the receipt index at ``path`` (None when absent).

    An unreadable file is ``io``; bad UTF-8, malformed JSON and every
    shape/key-order/ordering/digest or per-item semantic defect is
    ``state`` (a re-sealed file whose hash matches its tampered content
    still fails the per-item checks). The file is never truncated or
    rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_receipt_index_shape(data)


def _atomic_write_receipt_index(path: str, index: dict) -> None:
    """Write the index in declared key order and atomically replace ``path``."""
    ordered = {key: index[key] for key in RECEIPT_INDEX_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def advance_receipts(
    path: object,
    document: object,
    expected_tx_ids: object,
    trust: object,
) -> dict:
    """Verify a finalized-receipts batch and merge it into the index at ``path``.

    ``document``/``expected_tx_ids``/``trust`` are exactly the
    :func:`verify_finalized_receipts` arguments: the decoded
    ``POST /v1/transactions/finalized-receipts`` response (key order
    ``items, headers, finality``), the non-empty list of distinct
    64-lowercase-hex ids it must name, and the trust document carrying
    ``audit_signers``. The batch is fully verified first — nothing is
    read or written before verification succeeds — and the verified
    ``receipt, proof`` items are then merged **serially** into the
    version-1 index under the shared per-path lock.

    The index file carries the exact key order
    ``v, generation, finalized, items, hash``: ``v`` is 1; ``finalized``
    the closed ``{height, block_hash}`` boundary of the latest merged
    batch; ``items`` all known receipts in ``tx_id`` ascending order,
    each item in the fixed ``receipt, proof`` contract shape; and
    ``hash`` the 64-char lowercase hex SHA-256 of the canonical JSON of
    the other four fields. Serialization is compact UTF-8 JSON
    (non-ASCII unescaped) with one trailing LF, atomically replaced.

    The first successful change writes generation 1; every later change
    increments it exactly once. Merge rules: an incoming id already
    stored with the identical receipt/proof content is an idempotent
    no-op for that id, while the same id with different content is a
    conflict (``integrity``); the incoming finalized boundary may never
    move backwards, and at the same height it must name the same block
    hash (otherwise ``integrity``). A call that adds no receipt and
    leaves the boundary unchanged writes nothing and holds the
    generation. Success returns ``{"ok": True, "generation",
    "finalized", "added"}`` in that key order, ``added`` the number of
    previously unknown ids merged.

    Failure returns only ``{"ok": False, "error": category}`` with
    category one of ``input`` (argument or document structure; shared
    with the batch verifier), ``auth`` (unknown key version or a failed
    finality signature), ``integrity`` (batch verification, id content
    conflict, boundary regression or same-height/other-hash), ``state``
    (an existing index fails its parse, key-order, shape or digest
    checks, or one of its stored items fails the per-item semantic
    revalidation: confirmed status, recomputed tx_id, Ed25519 signature,
    receipt/proof inclusion-point binding or the Merkle sibling replay)
    and ``io`` (the index cannot be read or written; a failed
    write restores the original bytes best-effort). Nothing is raised
    and a failed call never changes the file bytes or the generation.
    """
    if not isinstance(path, str) or not path:
        return _failed_advance(ERR_INPUT)

    lock = _checkpoint_lock(path)
    with lock:
        # Stage 1 (input/auth/integrity): verify the whole batch offline,
        # reusing the shared batch contract, before any file is touched.
        try:
            result = verify_finalized_receipts(
                document, expected_tx_ids, trust
            )
        except Exception:
            # Defensive: the verifier never raises, but an unforeseeable
            # input must report rather than crash the caller.
            return _failed_advance(ERR_INPUT)
        if not result.get("ok"):
            return {"ok": False, "error": result["error"]}
        if not isinstance(document, dict):
            # Unreachable: the verifier pins the document shape; kept for
            # a strict typed boundary.
            return _failed_advance(ERR_INPUT)
        incoming_finalized = {
            key: result["finalized"][key] for key in HEADER_ANCHOR_KEYS
        }

        # The verified items, indexed by tx_id.
        incoming_items: dict[str, dict] = {}
        try:
            for raw_item in document["items"]:
                receipt = _parse_finalized_receipt_receipt(raw_item["receipt"])
                proof = _parse_finalized_receipt_proof(raw_item["proof"])
                incoming_items[receipt["tx_id"]] = {
                    "receipt": receipt,
                    "proof": proof,
                }
        except _Failure as failure:
            return _failed_advance(failure.category)

        # Stage 2 (state/io): the existing index is strictly loaded; a
        # missing file opens a new index at generation 0.
        try:
            stored = _load_receipt_index(path)
        except _CheckpointError as failure:
            return _failed_advance(failure.category)
        except Exception:
            # Defensive: an unreadable-by-surprise index must report
            # rather than crash the caller.
            return _failed_advance(ERR_STATE)

        if stored is None:
            generation = 0
            stored_finalized: dict | None = None
            merged_items: dict[str, dict] = {}
        else:
            generation = stored["generation"]
            stored_finalized = stored["finalized"]
            merged_items = {
                item["receipt"]["tx_id"]: item for item in stored["items"]
            }

        # Stage 3 (integrity): the boundary may never regress and at the
        # same height must name exactly the stored block hash.
        if stored_finalized is not None:
            if incoming_finalized["height"] < stored_finalized["height"]:
                return _failed_advance(ERR_INTEGRITY)
            if (
                incoming_finalized["height"] == stored_finalized["height"]
                and incoming_finalized["block_hash"]
                != stored_finalized["block_hash"]
            ):
                return _failed_advance(ERR_INTEGRITY)

        # Serial merge: identical content for a known id is idempotent;
        # any other content for the same id is a conflict.
        added = 0
        for tx_id in sorted(incoming_items):
            incoming_item = incoming_items[tx_id]
            stored_item = merged_items.get(tx_id)
            if stored_item is not None:
                if stored_item != incoming_item:
                    return _failed_advance(ERR_INTEGRITY)
                continue
            merged_items[tx_id] = incoming_item
            added += 1

        boundary_unchanged = (
            stored_finalized is not None
            and stored_finalized == incoming_finalized
        )
        if added == 0 and boundary_unchanged:
            # Idempotent: nothing merged and the boundary holds, so the
            # file bytes stay exactly as they were and the generation
            # holds.
            return {
                "ok": True,
                "generation": generation,
                "finalized": {
                    key: stored_finalized[key] for key in HEADER_ANCHOR_KEYS
                },
                "added": 0,
            }

        next_generation = generation + 1
        ordered_items = [merged_items[tx_id] for tx_id in sorted(merged_items)]
        index = {
            "v": RECEIPT_INDEX_VERSION,
            "generation": next_generation,
            "finalized": incoming_finalized,
            "items": ordered_items,
        }
        index["hash"] = _receipt_index_hash(
            next_generation, incoming_finalized, ordered_items
        )

        # Stage 4 (io): atomic replace; a failed write restores the
        # original bytes best-effort.
        try:
            original = _read_bytes_or_none(path)
        except OSError:
            return _failed_advance(ERR_IO)
        try:
            _atomic_write_receipt_index(path, index)
        except OSError:
            _restore_bytes(path, original)
            return _failed_advance(ERR_IO)
        except (TypeError, ValueError):
            # Defensive: a verified value JSON cannot serialize; do not
            # leave a partial file behind.
            _restore_bytes(path, original)
            return _failed_advance(ERR_INPUT)

        return {
            "ok": True,
            "generation": next_generation,
            "finalized": {
                key: incoming_finalized[key] for key in HEADER_ANCHOR_KEYS
            },
            "added": added,
        }


def advance_receipt_batches(
    path: object,
    documents: object,
    expected_tx_ids: object,
    trust: object,
) -> dict:
    """Verify an ordered run of finalized-receipt batches and merge them.

    ``documents`` is a non-empty list of decoded
    ``POST /v1/transactions/finalized-receipts`` responses and
    ``expected_tx_ids`` an equal-length list whose every element follows
    the single-batch rules (a non-empty list of distinct 64-lowercase-hex
    ids). ``trust`` is exactly the :func:`advance_receipts` trust
    document. Under the shared per-path lock the array shapes are
    validated first, then the version-1 index is loaded (a missing file
    opens at generation 0) and the batches are verified with

def _checkpoint_lock(path: str) -> threading.RLock:
    key = os.path.abspath(path)
    with _checkpoint_locks_guard:
        lock = _checkpoint_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _checkpoint_locks[key] = lock
        return lock


def _canonical_json_bytes(value: object) -> bytes:
    """Sorted-key, compact, unescaped-non-ASCII UTF-8 canonical JSON bytes."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _checkpoint_state_hash(generation: int, anchor: dict, tip: dict, context: dict) -> str:
    """SHA-256 over the canonical JSON bytes of every field but state_hash."""
    body = {
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "context": context,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _failed_advance(category: str) -> dict:
    return {"ok": False, "error": category}


def advance(
    path: str,
    docs: object,
    trust: object,
    anchor: object,
    now: object,
) -> dict:
    """Verify a range-export batch and durably checkpoint it at ``path``.

    ``docs`` is an ordered, non-empty batch of range deliveries verified with
    :func:`verify_range_exports` against ``trust`` and ``anchor`` at time
    ``now``: ``now`` must be a plain (non-boolean) non-negative integer; the
    first use of ``path`` requires a legal ``anchor`` (``{height, block_hash}``),
    while a later advance passes ``None`` (continue from the stored tip) or the
    stored tip's ``{height, block_hash}``.

    On success the checkpoint is written atomically (a uniquely named temp file
    in the same directory, fsynced and ``os.replace``d under a per-path lock)

def _serialize_document(ordered: dict) -> bytes:
    """Compact UTF-8 JSON (non-ASCII unescaped) with one trailing newline."""
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _atomic_write_checkpoint(path: str, checkpoint: dict) -> None:
    """Write the checkpoint in declared key order and atomically replace ``path``."""
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _atomic_write_bytes(path: str, payload: bytes) -> None:
    """Atomically replace ``path`` with ``payload``.

    The temp file is fsynced before the replace and the directory afterwards,
    mirroring the main store's durability rules.
    """
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".light-checkpoint-", dir=directory)
    promoted = False
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, path)
        promoted = True
        _fsync_dir(directory)
    finally:
        if not promoted and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _read_bytes_or_none(path: str) -> bytes | None:
    """Raw bytes of ``path`` (None when absent); other read errors propagate."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


def _restore_bytes(path: str, original: bytes | None) -> None:
    """Best-effort compensation: put ``original`` back at ``path``.

    A file that did not exist is unlinked again. Any failure is swallowed —
    the caller already reports ``io`` and the next strict load surfaces the
    corruption as ``state``.
    """
    try:
        if original is None:
            os.unlink(path)
        else:
            _atomic_write_bytes(path, original)
    except OSError:
        pass


def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so the checkpoint rename survives a crash."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)


# -- generation-history sidecar ------------------------------------------------


def _history_path(path: str) -> str:
    """The sidecar path mirroring one advance checkpoint path."""
    return path + ".history"

def _validate_header_anchor(raw: object) -> dict:
    """Structural validation of a closed ``{height, block_hash}`` anchor."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HEADER_ANCHOR_KEYS:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["height"]) or raw["height"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["block_hash"]):
        raise _Failure(ERR_INPUT)
    return {"height": raw["height"], "block_hash": raw["block_hash"]}


def _validate_header_trust(trust: object) -> dict:
    """Parse ``trust.audit_signers`` into ``{version: public_key}``.

    The list must be non-empty; every entry must carry a positive,
    non-boolean integer ``version`` and a 64-lowercase-hex ``public_key``.
    Versions must be unique. Any other defect is an input error.
    """
    if not isinstance(trust, dict):
        raise _Failure(ERR_INPUT)
    raw_signers = trust.get("audit_signers")
    if not isinstance(raw_signers, list) or not raw_signers:
        raise _Failure(ERR_INPUT)
    signers: dict[int, str] = {}
    for entry in raw_signers:
        if not isinstance(entry, dict):
            raise _Failure(ERR_INPUT)
        version = entry.get("version")
        public_key = entry.get("public_key")
        if not _is_int(version) or version < 1:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(public_key):
            raise _Failure(ERR_INPUT)
        if version in signers:
            raise _Failure(ERR_INPUT)
        signers[version] = public_key
    return signers


def _parse_header_page(document: object) -> tuple[dict, list[dict], dict, int, str]:
    """Stage 1 of the header-page contract: exact key order and raw types.

    Every defect here is an input error. Returns the closed anchor, the
    closed header items, the closed tip descriptor, the envelope's key
    version and its signature.
    """
    if not isinstance(document, dict):
        raise _Failure(ERR_INPUT)
    if tuple(document.keys()) != HEADER_PAGE_KEYS:
        raise _Failure(ERR_INPUT)
    page_anchor = _validate_header_anchor(document["anchor"])
    raw_headers = document["headers"]
    if not isinstance(raw_headers, list):
        raise _Failure(ERR_INPUT)
    headers: list[dict] = []
    for item in raw_headers:
        if not isinstance(item, dict) or tuple(item.keys()) != HEADER_ITEM_KEYS:
            raise _Failure(ERR_INPUT)
        if not _is_int(item["height"]) or item["height"] < 0:
            raise _Failure(ERR_INPUT)
        if (
            not crypto.is_hex64(item["prev_hash"])
            or not crypto.is_hex64(item["merkle_root"])
            or not crypto.is_hex64(item["block_hash"])
        ):
            raise _Failure(ERR_INPUT)
        if item["status"] not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise _Failure(ERR_INPUT)
        headers.append({key: item[key] for key in HEADER_ITEM_KEYS})
    raw_tip = document["tip"]
