        state_idempotent = stored is not None and stored["anchor"] == new_anchor
        if _sync_state_idempotent(
            step, checkpoint, parsed, new_anchor, account, stored
        ):
            # Full resubmission of the committed pair: neither file is
            # rewritten and both generations hold.
            return {
                "ok": True,
                "header": {
                    "generation": header_generation,
                    "tip": stored_tip,
                    "finalized": {
                        key: finalized[key] for key in HEADER_ANCHOR_KEYS
                    },
                    "applied": len(parsed),
                },
                "state": {
                    "generation": stored["generation"],
                    "anchor": {
                        key: stored["anchor"][key]
                        for key in STATE_ANCHOR_ANCHOR_KEYS
                    },
                },
            }

        next_header_generation = (
            header_generation if header_idempotent else header_generation + 1
        )
        next_steps = steps if same_step else steps + [step]
        new_checkpoint = {
            "v": HEADER_CHECKPOINT_VERSION,
            "generation": next_header_generation,
            "anchor": file_anchor,
            "tip": new_tip,
            "finalized": last_target,
            "steps": next_steps,
        }
        new_checkpoint["hash"] = _header_checkpoint_hash(
            HEADER_CHECKPOINT_VERSION,
            next_header_generation,
            file_anchor,
            new_tip,
            last_target,
            new_steps,
        )

        if stored is None:
            next_state_generation = 1
        elif state_idempotent:
            next_state_generation = stored["generation"]
        else:
            next_state_generation = stored["generation"] + 1
        state_ordered = {
            "v": STATE_ANCHOR_VERSION,
            "generation": next_state_generation,
            "account": account,
            "anchor": new_anchor,
            "document": state_document,
            "trust": trust,
        }
        state_ordered["hash"] = _state_anchor_hash(
            next_state_generation, account, new_anchor, state_document, trust
        )

        # Serialize both files before touching either one: a value JSON
        # cannot re-serialize is a caller-side input defect, never a
        # partial pair.
        try:
            header_payload = _header_checkpoint_payload(new_checkpoint)
            state_payload = _serialize_document(state_ordered)
        except (TypeError, ValueError):
            return _failed_advance(ERR_INPUT)

        state_path = _state_anchor_path(path)
        # Commit the pair: header first, sidecar last. A crash between
        # the two replaces leaves the old sidecar strictly bound to the
        # replayed old anchor (which is below the new finalized boundary),
        # so the next call treats it as stored state and advances it;
        # strict replay on load makes either complete pair the only
        # observable outcome. Both originals are captured first so a
        # failed write rolls the pair back best-effort.
        try:
            header_original = _read_bytes_or_none(path)
            state_original = _read_bytes_or_none(state_path)
        except OSError:
            return _failed_advance(ERR_IO)
        replaced: list[tuple[str, bytes | None]] = []
        try:
            _atomic_write_bytes(path, header_payload)
            replaced.append((path, header_original))
            if not state_idempotent or stored is None:
                _atomic_write_bytes(state_path, state_payload)
                replaced.append((state_path, state_original))
        except OSError:
            # Roll back every file already promoted, newest first; the
            # sidecar (written last) is restored before the header.
            for target, original in reversed(replaced):
                _restore_bytes(target, original)
